constraint NDS_DCACHE_UTAG_DEPTH {} {
        if {[selected NDS_DCACHE_UTAG_BITS] == 0} {
                set_opt_value NDS_DCACHE_UTAG_DEPTH 0
        } elseif {[selected NDS_DCACHE_SIZE] == 64} {
                set_opt_value NDS_DCACHE_UTAG_DEPTH 32
        } elseif {[selected NDS_DCACHE_SIZE] == 32} {
                set_opt_value NDS_DCACHE_UTAG_DEPTH 16
        } elseif {[selected NDS_DCACHE_SIZE] == 16} {
                set_opt_value NDS_DCACHE_UTAG_DEPTH 8
        }
}

constraint NDS_L2C_CACHE_SIZE_KB {} {
	set_opt_value NDS_L2C_CACHE_SIZE_KB 0

	if {[selected NDS_DCACHE_SIZE] == 0 || [selected NDS_ICACHE_SIZE] == 0} {
		set_opt_value NDS_L2C_CACHE_SIZE_KB 0
	}

    set constraint_list {}
    lappend constraint_list NDS_L2C_ECC_TYPE

    foreach constraint_item $constraint_list {
